mapper.select:
SELECT diary_id AS diaryId, image_url AS imageUrl, public_image_key AS publicImageKey FROM care_diary_image WHERE diary_id IN
#{diaryId}
ORDER BY diary_id, sort_order, image_id

mapper.update:
UPDATE care_diary_image
   SET public_image_key = #{publicImageKey}
WHERE image_id = #{imageId}

UPDATE care_diary
   SET publish_token = NULL,
       publishing_started_at = NULL
WHERE diary_id = #{diaryId}
  AND publish_token = #{token}

mapper.select:
SELECT r.report_id AS reportId, r.diary_id AS diaryId, r.reason, r.status, r.resolution, reporter.name AS reporterName, author.name AS authorName, p.name AS petName, LEFT(d.content, 100) AS contentPreview, r.created_at AS createdAt, r.resolved_at AS resolvedAt FROM diary_report r JOIN care_diary d ON d.diary_id = r.diary_id JOIN pet p ON p.pet_id = d.pet_id JOIN member reporter ON reporter.member_id = r.reporter_id JOIN member author ON author.member_id = d.author_member_id
WHERE r.status = #{status}
ORDER BY r.created_at DESC, r.report_id DESC LIMIT #{limit} OFFSET #{offset}
